export interface CatalogRecord {
  code: number;
  label: string;
  value: string;
  category: string;
  rank: number;
  style?: string;
  badge?: string;
  preferred: boolean;
  enabled: boolean;
  createdBy?: string;
  updatedBy?: string;
  note?: string;
}

export interface CatalogStore {
  insert(record: Omit<CatalogRecord, "code">): Promise<CatalogRecord>;
}

const textKeys = ["style", "badge", "createdBy", "updatedBy", "note"] as const;

export async function registerCatalogItem(
  store: CatalogStore,
  input: CatalogInput,
): Promise<CatalogRecord> {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    throw new TypeError("input must be an object");
  }
  const required = ["label", "value", "category"] as const;
  for (const key of required) {
    if (typeof input[key] !== "string" || input[key].length === 0) {
      throw new TypeError(`${key} must be a non-empty string`);
    }
  }
  const rank = input.rank ?? 0;
  if (!Number.isSafeInteger(rank) || rank < 0) {
    throw new RangeError("rank must be a non-negative safe integer");
  }
  for (const key of textKeys) {
    if (input[key] !== undefined && typeof input[key] !== "string") {
      throw new TypeError(`${key} must be a string`);
    }
  }
  if (input.preferred !== undefined && typeof input.preferred !== "boolean") {
    throw new TypeError("preferred must be boolean");
  }
  if (input.enabled !== undefined && typeof input.enabled !== "boolean") {
    throw new TypeError("enabled must be boolean");
  }
  const record: Omit<CatalogRecord, "code"> = {
    label: input.label.trim(),
    value: input.value.trim(),
    category: input.category.trim(),
    rank,
    preferred: input.preferred ?? false,
    enabled: input.enabled ?? true,
  };
  for (const key of textKeys) {
    const value = input[key];
    if (value !== undefined) record[key] = value;
  }
  return store.insert(record);
}

