import { CatalogInput, CatalogRecord, CatalogStore, registerCatalogItem } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
async function rejects(action: () => Promise<unknown>, kind: Function, message: string): Promise<unknown> {
  try { await action(); } catch (error) {
    assert(error instanceof kind, message);
    return error;
  }
  throw new Error(`${message}: did not reject`);
}

class RecordingStore implements CatalogStore {
  received: Omit<CatalogRecord, 'code'> | undefined;
  readonly result: CatalogRecord;
  constructor(result: CatalogRecord) { this.result = result; }
  async insert(record: Omit<CatalogRecord, 'code'>): Promise<CatalogRecord> {
    this.received = record;
    return this.result;
  }
}

(async () => {
  const stored: CatalogRecord = {
    code: 7, label: 'stored', value: 'v', category: 'c', rank: 0,
    preferred: false, enabled: true
  };
  const store = new RecordingStore(stored);
  const input: CatalogInput = { label: '  Label  ', value: '\tValue\n', category: ' Category ' };
  const before = { ...input };
  const returned = await registerCatalogItem(store, input);
  equal(returned, stored, 'store result identity is returned unchanged');
  assert(store.received !== undefined, 'insert was called');
  equal(store.received.label, 'Label', 'label is trimmed');
  equal(store.received.value, 'Value', 'value is trimmed');
  equal(store.received.category, 'Category', 'category is trimmed');
  equal(store.received.rank, 0, 'rank defaults to zero');
  equal(store.received.preferred, false, 'preferred defaults to false');
  equal(store.received.enabled, true, 'enabled defaults to true');
  assert(JSON.stringify(input) === JSON.stringify(before), 'input is not mutated');

  const fullStore = new RecordingStore(stored);
  const full: CatalogInput = {
    label: 'L', value: 'V', category: 'C', rank: Number.MAX_SAFE_INTEGER,
    style: '', badge: ' badge ', preferred: true, enabled: false,
    createdBy: ' creator ', updatedBy: '', note: ' note '
  };
  await registerCatalogItem(fullStore, full);
  const received = fullStore.received!;
  equal(received.rank, Number.MAX_SAFE_INTEGER, 'maximum safe rank is accepted');
  equal(received.style, '', 'empty optional text is preserved');
  equal(received.badge, ' badge ', 'optional text is not trimmed');
  equal(received.createdBy, ' creator ', 'createdBy is unchanged');
  equal(received.updatedBy, '', 'empty updatedBy is preserved');
  equal(received.note, ' note ', 'note is unchanged');
  equal(received.preferred, true, 'supplied preferred is preserved');
  equal(received.enabled, false, 'supplied enabled is preserved');

  const noopStore = new RecordingStore(stored);
  for (const bad of [null, undefined, 1, 'x', true]) {
    await rejects(() => registerCatalogItem(noopStore, bad as unknown as CatalogInput), TypeError, 'non-object is rejected');
  }
  for (const field of ['label', 'value', 'category'] as const) {
    const bad = { label: 'L', value: 'V', category: 'C', [field]: '   ' } as CatalogInput;
    await rejects(() => registerCatalogItem(noopStore, bad), TypeError, `${field} cannot be blank`);
    const wrong = { label: 'L', value: 'V', category: 'C', [field]: 3 } as unknown as CatalogInput;
    await rejects(() => registerCatalogItem(noopStore, wrong), TypeError, `${field} must be a string`);
  }
  for (const rank of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
    await rejects(() => registerCatalogItem(noopStore, { label: 'L', value: 'V', category: 'C', rank }), RangeError, 'invalid rank is rejected');
  }
  for (const field of ['style', 'badge', 'createdBy', 'updatedBy', 'note'] as const) {
    const bad = { label: 'L', value: 'V', category: 'C', [field]: 9 } as unknown as CatalogInput;
    await rejects(() => registerCatalogItem(noopStore, bad), TypeError, `${field} must be a string when supplied`);
  }

  const marker = new Error('store failure');
  const failing: CatalogStore = { insert: async () => { throw marker; } };
  const propagated = await rejects(
    () => registerCatalogItem(failing, { label: 'L', value: 'V', category: 'C' }),
    Error,
    'store error propagates'
  );
  equal(propagated, marker, 'the exact store error is propagated');
})();

